seif($item->status!=='attended' && in_array($item->status,['registered','waitlisted'])): ?><form method="POST" action="<?php echo e(route('knowledge.events.attendance',[$event,$item->user])); ?>"><?php echo csrf_field(); ?><button class="rounded-xl border px-3 py-1.5 text-sm text-blue-700">Mark attended</button></form><?php endif; ?></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_0): ?><p class="py-4 text-slate-500">No registrations yet.</p><?php endif; ?></div></section><?php endif; ?>
