plete</option><option value="cancelled">Cancel</option></select><textarea name="reason" class="w-full rounded-xl border-slate-300" placeholder="Reason required when cancelling"></textarea><button class="w-full rounded-xl bg-slate-900 px-4 py-2 text-white">Update status</button></form></section><?php endif; ?></aside></div>
